    }
  }
}

{
  "name": "usewrit",
  "interface": {
    "displayName": "Writ"
  },
  "plugins": [
    {
      "name": "writ",
      "source": {
        "source": "local",
        "path": "./"
      },
      "policy": {
        "installation": "AVAILABLE",
        "authentication": "ON_INSTALL"
      },
      "category": "Productivity"
    }
  ]
}

{
  "name": "writ",
  "version": "1.0.7",
  "description": "Writ turns a website into something you can call: read a page, collect a site, build a real API from it, or run a task on a site the user is signed in to.",
  "mcpServers": {
    "writ-cloud": {
      "httpUrl": "https://api.usewrit.app/mcp?payments=off"
    }
  },
  "contextFileName": "GEMINI.md"
}

{
  "$schema": "https://anthropic.com/claude-code/marketplace.schema.json",
